import{_ as e,o,c as a,a2 as i}from"./chunks/framework.BXzK3EA4.js";const n="/assets/253_03acb948-e30f-48ac-a123-f968143fabdc.CvMfRtFp.png",r="/assets/255_32cf100f-a7cb-43e9-b6e1-f95f7f8cef81.CE7WST-B.png",m=JSON.parse('{"title":"How to Reinstall the Operating System on a Physical Server","description":"","frontmatter":{"title":"How to Reinstall the Operating System on a Physical Server"},"headers":[],"relativePath":"operations-knowledge-base/dedicated-server/how-to-reinstall-the-operating-system-on-a-physical-server.md","filePath":"operations-knowledge-base/dedicated-server/how-to-reinstall-the-operating-system-on-a-physical-server.md","lastUpdated":1794292919000}'),s={name:"operations-knowledge-base/dedicated-server/how-to-reinstall-the-operating-system-on-a-physical-server.md"};function l(u,t,c,h,p,d){return o(),a("div",null,[...t[0]||(t[0]=[i('<p>During server usage, you may encounter situations where you need to change the operating system, troubleshoot system issues, or reconfigure disk partitions. The <strong>&quot;Reinstall the system&quot;</strong> feature in the control panel allows you to conveniently reinstall the server&#39;s operating system to meet different operational requirements.</p><h2 id="i-access-path" tabindex="-1">I.Access Path <a class="header-anchor" href="#i-access-path" aria-label="Permalink to &quot;I.Access Path&quot;">​</a></h2><ol><li>Log in to the platform and go to the <strong>&quot;Customer Center&quot;</strong>. Under <strong>&quot;My Orders&quot;</strong>, click <strong>&quot;Physical Servers&quot;</strong>. Alternatively, go to <strong>&quot;Product Management&quot;</strong>, click <strong>&quot;Physical Servers&quot;</strong>, and filter the server list by region and status.</li><li>On the <strong>&quot;Manage Products&quot;</strong> page, you can view the server&#39;s basic information. Click the <strong>&quot;Server Information&quot;</strong> tab at the top, then locate and click the <strong>&quot;Reinstall the system&quot;</strong> button in the action button area.</li></ol><p><img src="'+n+'" alt=""></p><h2 id="ii-procedure" tabindex="-1">II.Procedure <a class="header-anchor" href="#ii-procedure" aria-label="Permalink to &quot;II.Procedure&quot;">​</a></h2><h3 id="_1-click-the-reinstall-the-system-button" tabindex="-1">1. Click the &quot;Reinstall the system&quot; Button <a class="header-anchor" href="#_1-click-the-reinstall-the-system-button" aria-label="Permalink to &quot;1. Click the &quot;Reinstall the system&quot; Button&quot;">​</a></h3><p>Clicking the <strong>&quot;Reinstall the system&quot;</strong> button will open the <strong>&quot;Reinstall the system&quot;</strong> window.</p><h3 id="_2-configure-reinstallation-options" tabindex="-1">2. Configure Reinstallation Options <a class="header-anchor" href="#_2-configure-reinstallation-options" aria-label="Permalink to &quot;2. Configure Reinstallation Options&quot;">​</a></h3><ul><li><strong>Select Operating System:</strong> From the <strong>&quot;Operating system&quot;</strong> dropdown menu, select the appropriate OS version according to your requirements.</li><li><strong>Set Password:</strong> In the <strong>&quot;system Code&quot;</strong> field, set the login password for the operating system. You can also click the <strong>&quot;Random&quot;</strong> button to automatically generate a strong password.</li><li><strong>Set Port:</strong> In the <strong>&quot;Port&quot;</strong> field, set the port used for remote access to the server. You can also click the <strong>&quot;Random&quot;</strong> button to generate a random port.</li></ul><h3 id="_3a-select-partition-type-windows" tabindex="-1">3a. Select Partition Type (Windows) <a class="header-anchor" href="#_3a-select-partition-type-windows" aria-label="Permalink to &quot;3a. Select Partition Type (Windows)&quot;">​</a></h3><ul><li><p><strong>Full format:</strong> Selecting this option will format the entire disk of the server and erase all data. Please proceed with caution. This option is typically used when you need to completely clean server data or switch to a different operating system.</p></li><li><p><strong>First partition format:</strong> Only the first partition of the server will be formatted, while data on other partitions will remain. This is suitable when you only need to reinstall the operating system but want to retain data on other partitions.</p></li><li><p><strong>Select Partition Method:</strong></p><ul><li><strong>Default partition:</strong> The system will partition the disk automatically using the default configuration.</li><li><strong>Custom partition:</strong> If you have specific partition requirements, such as defining partition size or file system type, you can manually configure the disk partitions using this option.</li></ul></li><li><p><strong>Data Backup Notice:</strong> Before proceeding, please carefully read the warning: &quot;All data will be lost during reinstallation. Please confirm that you have backed up your data.&quot; If your important data has been backed up, check the confirmation box.</p></li></ul><h3 id="_3b-linux-partition-options" tabindex="-1">3b. Linux Partition Options <a class="header-anchor" href="#_3b-linux-partition-options" aria-label="Permalink to &quot;3b. Linux Partition Options&quot;">​</a></h3><ul><li><p>Linux system reinstallation does <strong>not support retaining existing data</strong>. Confirming the reinstallation means the entire disk will be formatted and the data cannot be recovered. Please ensure that all important data has been backed up beforehand.</p></li><li><p>Available partition options include:</p><ul><li><strong>Default partition:</strong> The system will automatically partition the disk using the default configuration.</li><li><strong>Additional configuration:</strong> Provides additional partition configuration options to meet specific requirements.</li><li><strong>Custom partition:</strong> Allows manual configuration of partition size and file system type.</li></ul></li><li><p><strong>Data Backup Notice:</strong> Before proceeding, please carefully read the warning: &quot;All data will be lost during reinstallation. Please confirm that you have backed up your data.&quot; If your important data has been backed up, check the confirmation box.</p></li></ul><p><img src="'+r+'" alt=""></p><h3 id="_4-confirm-reinstallation" tabindex="-1">4. Confirm Reinstallation <a class="header-anchor" href="#_4-confirm-reinstallation" aria-label="Permalink to &quot;4. Confirm Reinstallation&quot;">​</a></h3><p>After completing all configurations, click <strong>&quot;Confirm reload&quot;</strong>. The system will begin reinstalling the operating system. During this process, the server will be temporarily unavailable. You can monitor the installation status from the <strong>&quot;Product Details&quot;</strong> page and wait for the reinstallation to complete.</p><h3 id="_5-login-information" tabindex="-1">5. Login Information <a class="header-anchor" href="#_5-login-information" aria-label="Permalink to &quot;5. Login Information&quot;">​</a></h3><p>After the reinstallation is complete, the new login information can be viewed under <strong>&quot;Information software&quot;</strong>. Click the <strong>&quot;*&quot;</strong> icon to reveal the login password.</p><h2 id="iii-important-notes" tabindex="-1">III.Important Notes <a class="header-anchor" href="#iii-important-notes" aria-label="Permalink to &quot;III.Important Notes&quot;">​</a></h2><ol><li><strong>Data Backup:</strong> Before performing a system reinstallation, make sure all important server data has been backed up to prevent permanent data loss.</li><li><strong>Waiting Time:</strong> The time required for system reinstallation may vary depending on server performance, network conditions, and the operating system installation process. Please be patient while the installation completes.</li></ol>',20)])])}const f=e(s,[["render",l]]);export{m as __pageData,f as default};
